  define({number:'SOP-QM-002',title:'Rollen, Verantwortlichkeiten und Qualifikation',area:'Qualitätsmanagement',keywords:['Rolle','Qualifikation','Unterweisung','Skillmatrix'],processOwner:'Qualitätsverantwortlicher / Führungskraft',scope:'Alle Mitarbeiter und Funktionsrollen',purpose:'Sicherstellen, dass Tätigkeiten nur von Personen durchgeführt werden, die dafür eingewiesen, qualifiziert und organisatorisch berechtigt sind.',processFlow:['Tätigkeit bestimmen','Anforderung prüfen','Person zuordnen','Qualifikation nachweisen','Einsatz freigeben'],definitions:['Qualifikation: nachgewiesene Befähigung für eine Tätigkeit.','Unterweisung: dokumentierte Vermittlung notwendiger Arbeits- oder Sicherheitsinformationen.'],responsibilities:['Führungskräfte stellen die geeignete Besetzung sicher.','Mitarbeiter führen nur freigegebene Tätigkeiten aus.','Funktionsverantwortliche pflegen erforderliche Qualifikationsnachweise.'],prerequisites:['Rollen und Tätigkeiten sind bekannt.','Erforderliche Qualifikationen sind definiert.'],resources:['Skillmatrix','Unterweisungsnachweise','Benutzer- und Rollenverwaltung'],steps:['Für die geplante Tätigkeit die erforderliche Rolle und Qualifikation bestimmen.','Vor Einsatz prüfen, ob der vorgesehene Mitarbeiter ausreichend eingewiesen und qualifiziert ist.','Bei Stapler- oder VNA-Tätigkeiten den gültigen Qualifikationsnachweis prüfen.','Mitarbeiter nur innerhalb seiner Berechtigung einsetzen.','Neue oder wesentlich geänderte SOPs den betroffenen Mitarbeitern bekannt machen beziehungsweise unterweisen.','Qualifikations- oder Rollenänderungen nachvollziehbar dokumentieren.','Bei fehlender Qualifikation eine geeignete Ersatzperson einsetzen oder die Tätigkeit stoppen.'],checks:['Qualifikationsnachweis ist gültig.','Rolle und Systemrechte passen zur Aufgabe.'],deviations:['Fehlt eine erforderliche Qualifikation, darf die Tätigkeit nicht eigenmächtig ausgeführt werden. Die Führungskraft entscheidet über Ersatzbesetzung oder Schulungsbedarf.',EXTERNAL],records:['Skillmatrix','Unterweisungsnachweis','Rollen-/Rechtezuordnung'],metrics:['Anteil gültiger Pflichtqualifikationen','Überfällige Unterweisungen'],relatedDocuments:['SOP-SYS-001 – Benutzer, Rollen und Zugriffsrechte','SOP-ORG-002 – Schicht- und Personaleinsatzplanung'],references:['SOP-SYS-001','SOP-ORG-002']}),

  define({number:'SOP-QM-003',title:'Abweichungen und Korrekturmaßnahmen',area:'Qualitätsmanagement',keywords:['Abweichung','Fehler','Korrektur','Ursache','CAPA'],processOwner:'Qualitätsverantwortlicher',scope:'Alle qualitätsrelevanten Prozesse',purpose:'Abweichungen kontrolliert behandeln, Ursachen beseitigen und Wiederholungen wirksam verhindern.',processFlow:['Abweichung erkennen','Prozess sichern','Ursache bewerten','Maßnahme umsetzen','Wirksamkeit prüfen'],definitions:['Abweichung: Nichterfüllung einer festgelegten Anforderung.','Korrekturmaßnahme: Maßnahme zur Beseitigung der Ursache einer Abweichung.'],responsibilities:['Jeder Mitarbeiter meldet erkannte Abweichungen.','Prozessverantwortliche sichern den betroffenen Prozess.','Qualitätsverantwortliche koordinieren Ursachenanalyse und Wirksamkeitsprüfung bei relevanten Fällen.'],prerequisites:['Betroffener Vorgang ist identifizierbar.'],resources:['ExportHUB Fehlerdiagnose','Aufgaben-/Maßnahmenverwaltung','Prozessnachweise'],steps:['Abweichung sofort erkennen und betroffenen Vorgang eindeutig identifizieren.','Bei Risiko falscher Ware, Dokumente oder Daten die weitere Bearbeitung stoppen.','Abweichung mit Datum, Vorgang, Beschreibung und Melder dokumentieren.','Sofortkorrektur festlegen, wenn der Fehler sicher behoben werden kann.','Bei wiederkehrender oder erheblicher Abweichung die Ursache systematisch analysieren.','Korrekturmaßnahme, Verantwortlichen und Termin festlegen.','Maßnahme durchführen und Ergebnis dokumentieren.','Nach angemessener Zeit prüfen, ob die Maßnahme wirksam war und der Fehler nicht erneut auftritt.','Fall erst nach dokumentierter Wirksamkeitsprüfung schließen.'],checks:['Betroffener Vorgang ist gesichert.','Ursache und Maßnahme sind voneinander unterschieden.','Verantwortlicher und Termin sind benannt.'],deviations:['Bei Systemstörungen zusätzlich SOP-SYS-002 anwenden. Bei unmittelbarem Qualitäts- oder Sicherheitsrisiko bleibt der Prozess gesperrt, bis eine verantwortliche Person freigibt.'],records:['Abweichungsbericht','Ursachenanalyse','Maßnahmen- und Wirksamkeitsnachweis'],metrics:['Wiederholungsabweichungen','Überfällige Maßnahmen','Durchlaufzeit bis Abschluss'],relatedDocuments:['SOP-SYS-002 – Fehler und Systemstörungen','SOP-QM-004 – Reklamationen und Kundenfeedback'],references:['SOP-SYS-002','SOP-QM-004']}),

  define({number:'SOP-QM-004',title:'Reklamationen und Kundenfeedback',area:'Qualitätsmanagement',keywords:['Reklamation','Kunde','Feedback','POD'],processOwner:'Qualitätsverantwortlicher / zuständiger Prozessverantwortlicher',scope:'Kundenbezogene Reklamationen und Rückmeldungen',purpose:'Kundenreklamationen vollständig, nachvollziehbar und mit wirksamer Ursachenbearbeitung behandeln.',processFlow:['Reklamation erfassen','Vorgang zuordnen','Sachverhalt prüfen','Korrektur einleiten','Kunde informieren','Abschließen'],responsibilities:['Empfänger der Reklamation erfasst den Sachverhalt.','Prozessverantwortliche prüfen den betroffenen Ablauf.','Qualitätsverantwortliche koordinieren relevante Korrekturmaßnahmen.'],prerequisites:['Kunde und möglichst Sendungs-/Auftragsbezug sind bekannt.'],resources:['ExportHUB Sendungshistorie','Versanddokumente','POD','Reklamationsnachweis'],steps:['Reklamation mit Kunde, Datum, Ansprechpartner und Sachverhalt erfassen.','Betroffene Sendung oder Leistung eindeutig zuordnen.','Statushistorie, Lieferschein, CMR, ABD, POD und weitere relevante Nachweise prüfen.','Feststellen, ob eine sofortige Kunden- oder Prozessmaßnahme erforderlich ist.','Ursache der Reklamation bewerten und bei internem Prozessfehler SOP-QM-003 anwenden.','Kundenrückmeldung durch die zuständige Person veranlassen und Zusagen dokumentieren.','Erledigte Maßnahmen und Ergebnis dokumentieren.','Reklamation erst schließen, wenn Bearbeitung und erforderliche Rückmeldung abgeschlossen sind.'],checks:['Vorgang ist eindeutig zugeordnet.','Kundenzusage und interner Maßnahmenstatus stimmen überein.'],deviations:['Kann der Vorgang nicht eindeutig zugeordnet werden, wird keine Ursache vermutet; fehlende Angaben werden gezielt nachgefordert.'],records:['Reklamationsdatensatz','Kundenkommunikation','Korrekturmaßnahmen','zugehörige Versandnachweise'],metrics:['Anzahl Reklamationen','Wiederholungsreklamationen','Bearbeitungsdauer'],relatedDocuments:['SOP-QM-003 – Abweichungen und Korrekturmaßnahmen','SOP-LOG-012 – POD und Abliefernachweis'],references:['SOP-QM-003','SOP-LOG-012']}),

  define({number:'SOP-QM-005',title:'Interne Prüfung und kontinuierliche Verbesserung',area:'Qualitätsmanagement',keywords:['Audit','KVP','Verbesserung','Kennzahlen'],processOwner:'Qualitätsverantwortlicher',scope:'Alle im Qualitätsmanagement relevanten Prozesse',purpose:'Die Wirksamkeit der Prozesse regelmäßig bewerten und Verbesserungen nachvollziehbar planen, umsetzen und überprüfen.',processFlow:['Daten sammeln','Bewerten','Maßnahme planen','Umsetzen','Wirksamkeit prüfen'],responsibilities:['Qualitätsverantwortliche planen interne Prüfungen.','Prozessverantwortliche stellen Nachweise bereit und setzen vereinbarte Maßnahmen um.'],prerequisites:['Aktuelle Prozessdaten und Nachweise sind verfügbar.'],resources:['KPI-Auswertungen','Reklamationen','Abweichungen','Auditnachweise','Verbesserungsvorschläge'],steps:['Prüfumfang und zu betrachtende Prozesse festlegen.','Aktuelle Kennzahlen, Abweichungen, Reklamationen, Systemfehler und frühere Maßnahmen zusammenstellen.','Stichprobenartig prüfen, ob SOP und tatsächliche Durchführung übereinstimmen.','Feststellungen sachlich dokumentieren und nach Bedeutung bewerten.','Bei Handlungsbedarf konkrete Maßnahme, Verantwortlichen und Termin festlegen.','Maßnahme entsprechend SOP-QM-003 verfolgen.','Nach Umsetzung die Wirksamkeit bewerten.','Ergebnisse für Managementbewertung und weitere Prozessverbesserung bereitstellen.'],checks:['Feststellung ist mit einem nachvollziehbaren Nachweis belegt.','Maßnahmen besitzen Verantwortlichen und Termin.'],deviations:['Kritische Feststellungen, die eine fehlerhafte Leistung verursachen können, sind sofort als Abweichung gemäß SOP-QM-003 zu behandeln.'],records:['Audit-/Prüfbericht','Maßnahmenliste','Wirksamkeitsnachweis'],metrics:['Abgeschlossene Auditmaßnahmen','Überfällige Maßnahmen','Wiederholungsfeststellungen'],relatedDocuments:['SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-QM-003']}),

  define({number:'SOP-SYS-001',title:'Benutzer, Rollen und Zugriffsrechte',area:'System / ExportHUB',keywords:['Benutzer','Rollen','Rechte','Firma','Admin','HSE'],processOwner:'Systemadministrator',scope:'ExportHUB Benutzer- und Firmenzugriffe',purpose:'Sicherstellen, dass jeder Benutzer nur auf die für seine Firma und Rolle zulässigen Daten und Funktionen zugreifen kann.',processFlow:['Benutzer anlegen','Firma zuordnen','Rolle vergeben','Rechte prüfen','Zugriff überwachen'],responsibilities:['Systemadministratoren verwalten systemweite Berechtigungen.','Firmenadministratoren verwalten zulässige Benutzer ihrer Firma.','HSE / Sicherheitsverantwortliche werden innerhalb ihrer Firma hinsichtlich der Firmenadministration wie Firmenadministratoren behandelt.'],prerequisites:['Identität, Firma und benötigte Rolle des Benutzers sind bestätigt.'],resources:['ExportHUB Benutzerverwaltung','Firmenverwaltung','Rechtematrix'],steps:['Benutzer eindeutig anlegen oder bestehenden Benutzer auswählen.','Benutzer genau der vorgesehenen Firma beziehungsweise den ausdrücklich freigegebenen Firmen zuordnen.','Passende Rolle und erforderliche Funktionsrechte vergeben.','Prüfen, ob normale Firmenbenutzer ausschließlich Daten ihrer eigenen Firma sehen können.','Bei Firmenadministrator oder HSE/Sicherheitsverantwortlichem die freigegebenen Firmenverwaltungsrechte anwenden.','Systemadministratorrechte nur vergeben, wenn firmenübergreifender Zugriff fachlich erforderlich und autorisiert ist.','Nach Rollenänderung Anmeldung beziehungsweise Rechte neu prüfen.','Nicht mehr benötigte Konten deaktivieren oder entsprechend der gültigen Löschregel entfernen.','Verdächtige oder firmenübergreifende Fehlzugriffe sofort als Sicherheits-/Systemabweichung behandeln.'],checks:['Firma und Rolle stimmen mit dem Auftrag überein.','Kein unzulässiger firmenübergreifender Zugriff.','SOP-Rechte entsprechen read/edit/admin-Systematik.'],deviations:['Bei unzulässiger Datensicht Zugriff sofort begrenzen und SOP-SYS-002 sowie SOP-QM-003 anwenden.'],records:['Benutzerstamm','Rollen- und Rechtezuordnung','Änderungsprotokoll'],metrics:['Unberechtigte Zugriffsereignisse','Offene Benutzerbereinigungen'],relatedDocuments:['SOP-QM-002 – Rollen, Verantwortlichkeiten und Qualifikation','SOP-SYS-002 – Fehler und Systemstörungen'],references:['SOP-QM-002','SOP-SYS-002']}),

  define({number:'SOP-SYS-002',title:'Fehler und Systemstörungen',area:'System / ExportHUB',keywords:['Fehler','Störung','Diagnose','App','System'],processOwner:'Systemadministrator / Prozessverantwortlicher',scope:'ExportHUB und angebundene technische Funktionen',purpose:'Systemfehler sicher behandeln, ohne falsche Daten, Dokumente oder unkontrollierte Prozessfortsetzungen zu erzeugen.',processFlow:['Fehler erkennen','Vorgang sichern','Diagnose erfassen','Beheben','Nachprüfen'],responsibilities:['Mitarbeiter melden Fehler mit konkretem Vorgangsbezug.','Administratoren analysieren technische Ursachen.','Prozessverantwortliche entscheiden über fachliche Fortsetzung nach der Behebung.'],prerequisites:['Fehlerbild oder betroffener Vorgang ist identifizierbar.'],resources:['ExportHUB Fehlerdiagnose','Benachrichtigungen','Browser-/App-Fehlermeldung','GitHub/Azure Diagnose soweit berechtigt'],steps:['Fehler feststellen und betroffenen Prozess beziehungsweise Datensatz identifizieren.','Prüfen, ob durch Fortsetzung falsche Daten oder Dokumente entstehen könnten.','Bei Risiko die Bearbeitung stoppen.','Fehlerdiagnose mit Zeitpunkt, Benutzerkontext, Firma, Funktion und Fehlermeldung sichern.','Technische Analyse durchführen beziehungsweise an zuständige Stelle weitergeben.','Keine Pflichtprüfung oder Berechtigung durch manuelle Datenmanipulation umgehen.','Nach Korrektur den ursprünglichen Vorgang erneut vollständig prüfen.','Nur bei erfolgreicher Prüfung den normalen Prozess fortsetzen.'],checks:['Diagnose enthält genügend Kontext zur Reproduktion.','Firmen- und Datenschutzgrenzen bleiben auch bei Fehlerdiagnosen erhalten.'],deviations:['Bei Ausfall eines externen Systems gilt: '+EXTERNAL],records:['Fehlerdiagnose','Korrekturcommit/-maßnahme','Prüfnachweis'],metrics:['Fehlerhäufigkeit','Wiederholungsfehler','Zeit bis Wiederherstellung'],relatedDocuments:['SOP-QM-003 – Abweichungen und Korrekturmaßnahmen','SOP-SYS-004 – Änderungen und Softwarefreigaben'],references:['SOP-QM-003','SOP-SYS-004']}),

  define({number:'SOP-SYS-003',title:'Datensicherung und Wiederherstellung',area:'System / ExportHUB',keywords:['Backup','Restore','Datensicherung','Archiv'],processOwner:'Systemadministrator',scope:'Geschäftsrelevante ExportHUB-Daten und Konfigurationen',purpose:'Geschäftsrelevante Daten gegen unbeabsichtigten Verlust schützen und eine kontrollierte Wiederherstellung ermöglichen.',processFlow:['Sicherung planen','Sicherung erstellen','Erfolg prüfen','Aufbewahren','Restore testen'],responsibilities:['Systemadministratoren überwachen Sicherungen und Wiederherstellungstests.','Prozessverantwortliche unterstützen die fachliche Plausibilitätsprüfung nach einem Restore.'],prerequisites:['Sicherungsziele und Aufbewahrungsregeln sind definiert.'],resources:['Tägliche Sicherung','Monatliche Sicherung','Jährliche Langzeitarchivierung'],steps:['Sicherungsumfang für produktive Daten und notwendige Konfigurationen festlegen.','Tägliche Sicherung automatisiert erzeugen und Erfolg überwachen.','Monatliche Sicherung gemäß Aufbewahrungsregel kennzeichnen.','Jährliche Langzeitkopie getrennt und nachvollziehbar aufbewahren.','Fehlgeschlagene Sicherungen als Störung behandeln und erneut absichern.','In festgelegten Intervallen eine Wiederherstellung in einer sicheren Testumgebung durchführen.','Nach Wiederherstellung Datenvollständigkeit und Firmenzuordnung fachlich prüfen.','Restore-Test dokumentieren.'],checks:['Sicherung ist lesbar und eindeutig datiert.','Restore verändert nicht unbeabsichtigt die Produktionsdaten.'],deviations:['Die technische Wiederherstellung in der Infrastruktur erfolgt gemäß SOP XXXX.'],records:['Backup-Protokoll','Fehlerprotokoll','Restore-Testnachweis'],metrics:['Erfolgsquote Sicherungen','Alter des letzten erfolgreichen Restore-Tests'],relatedDocuments:['SOP-SYS-002 – Fehler und Systemstörungen'],references:['SOP-SYS-002']}),

  define({number:'SOP-SYS-004',title:'Änderungen und Softwarefreigaben',area:'System / ExportHUB',keywords:['Release','Test','GitHub','Deployment','Änderung'],processOwner:'Systemadministrator / Softwareverantwortlicher',scope:'Änderungen an ExportHUB Website, API, App und Konfiguration',purpose:'Softwareänderungen kontrolliert entwickeln, testen, freigeben und veröffentlichen, ohne die Produktion ungeprüft zu verändern.',processFlow:['Änderung beschreiben','Isoliert entwickeln','Testen','Freigeben','Veröffentlichen','Nachprüfen'],responsibilities:['Entwicklung setzt Änderungen isoliert um.','Verantwortliche prüfen Tests und Releasekriterien.','Produktion wird erst nach dokumentierter Freigabe aktualisiert.'],prerequisites:['Anforderung und Zielzustand sind beschrieben.','Aktueller Ausgangsstand ist bekannt.'],resources:['GitHub Branches','automatisierte Tests','TESTSERVICE','Release Center'],steps:['Änderung fachlich beschreiben und Risiko für bestehende Funktionen bewerten.','Separaten Entwicklungs- oder Releasezweig auf aktuellem Ausgangsstand verwenden.','Vor der Korrektur bei Fehlern zunächst konkrete Ursache bestimmen und reproduzierbaren Test erstellen.','Änderung umsetzen, ohne Produktion direkt zu bearbeiten.','Betroffene Teiltests und bestehende Regressionstests ausführen.','Bei UI-/Prozessänderungen TESTSERVICE beziehungsweise geeignete Vorschau prüfen.','Nur einen vollständig geprüften Stand zur Freigabe vorlegen.','Freigegebene Version eindeutig kennzeichnen.','Veröffentlichung kontrolliert über den vorgesehenen Releaseprozess durchführen.','Nach Veröffentlichung Smoke-Test durchführen und bei erheblichem Fehler kontrolliert zurückrollen.'],checks:['Keine ungeprüfte Direktänderung an Produktion.','Tests passen zur tatsächlichen Fehlerursache.','Releaseversion ist eindeutig.'],deviations:['Fehlgeschlagene Tests werden nicht durch erneutes blindes Ausführen als gelöst betrachtet; Ursache ist gemäß SOP-SYS-002 zu analysieren.'],records:['Commit-/Releasehistorie','Testergebnis','Freigabenachweis'],metrics:['Fehlgeschlagene Releases','Regressionen nach Release'],relatedDocuments:['SOP-SYS-002 – Fehler und Systemstörungen','SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-SYS-002','SOP-QM-003']}),

  define({number:'SOP-LOG-001',title:'Versandauftrag übernehmen und prüfen',area:'Versand und Export',keywords:['Versandauftrag','Auftrag','Prüfung','Sendung'],processOwner:'Versand / Export',scope:'Alle neu anzulegenden Versandvorgänge',purpose:'Nur vollständige und plausible Versandaufträge zur weiteren Versandbearbeitung freigeben.',processFlow:['Auftrag übernehmen','Stammdaten prüfen','Versanddaten prüfen','Exportbedarf prüfen','Sendung anlegen'],responsibilities:['Versandmitarbeiter prüfen den Auftrag vor Anlage der Sendung.'],prerequisites:['Versandauftrag ist im Quellsystem verfügbar.'],resources:['ExportHUB','Auftrags-/ERP-Daten','Kundenstammdaten'],steps:['Versandauftrag aus dem vorgesehenen System übernehmen.','Kundennummer und Empfängerzuordnung prüfen.','Lieferscheinnummer beziehungsweise Versandbezug prüfen.','Zielland, Menge, Verpackung und erforderlichen Versandtermin prüfen.','Besondere Kunden- oder Transportanforderungen identifizieren.','Prüfen, ob Nicht-EU-, Zoll- oder ABD-Anforderungen vorliegen können.','Fehlende Pflichtinformationen vor weiterer Bearbeitung klären.','Sendung im ExportHUB anlegen beziehungsweise vorhandene Sendung eindeutig öffnen.'],checks:['Kunde und Empfänger sind eindeutig.','Zielland und Lieferscheinbezug sind plausibel.'],deviations:['Unklare Stammdaten nicht durch Vermutung ersetzen; Klärung gemäß SOP-LOG-002 durchführen.'],records:['Sendungsdatensatz','Auftragsreferenz'],metrics:['Anzahl unvollständiger Versandaufträge'],relatedDocuments:['SOP-LOG-002 – Kunden- und Empfängerdaten','SOP-LOG-007 – ABD und Zollabwicklung'],references:['SOP-LOG-002','SOP-LOG-007']}),

  define({number:'SOP-LOG-002',title:'Kunden- und Empfängerdaten',area:'Versand und Export',keywords:['Kunde','Empfänger','Adresse','Standort'],processOwner:'Versand / Stammdatenverantwortlicher',scope:'Kunden- und Empfängerdaten in Versandvorgängen',purpose:'Sicherstellen, dass Versanddokumente und Transportaufträge die richtige Kunden- und Lieferadresse verwenden.',processFlow:['Kunde wählen','Standort wählen','Adresse prüfen','Abweichung klären','Übernehmen'],responsibilities:['Versand prüft die im Vorgang verwendeten Daten.','Stammdatenverantwortliche pflegen dauerhaft gültige Änderungen.'],prerequisites:['Kundennummer oder eindeutiger Kundenbezug ist vorhanden.'],resources:['ExportHUB Kundenstamm','ERP-Stammdaten'],steps:['Kunden anhand der eindeutigen Kundennummer auswählen.','Nur einen Standort verwenden, der diesem Kunden zugeordnet ist.','Empfängername, Straße, Hausnummer, Postleitzahl, Ort und Land kontrollieren.','Erforderliche Ansprechpartner- und Kontaktdaten prüfen.','Bei Abweichung zwischen Auftrag und Stamm zunächst die Ursache klären.','Keine Adresse eines anderen Kunden als Ersatz verwenden.','Neue oder dauerhaft geänderte Standorte über den vorgesehenen Stammdatenprozess pflegen.','Geprüfte Adresse in die Sendung übernehmen.'],checks:['Standort gehört zum ausgewählten Kunden.','Land ist eindeutig und korrekt.'],deviations:['Änderung im externen ERP-System erfolgt gemäß SOP XXXX.'],records:['Kunden-/Standortstamm','Sendungsadresse'],metrics:['Adresskorrekturen vor Versand','Adressbezogene Reklamationen'],relatedDocuments:['SOP-LOG-001 – Versandauftrag übernehmen und prüfen'],references:['SOP-LOG-001']}),

  define({number:'SOP-LOG-003',title:'Verpackung, Colli, Gewicht und LDM',area:'Versand und Export',keywords:['Colli','Palette','Gewicht','LDM','Verpackung'],processOwner:'Versand / Lager',scope:'Physische Verpackungs- und Mengendaten jeder Sendung',purpose:'Die tatsächlich versendeten Verpackungseinheiten mit korrekter Anzahl, Gewicht, Abmessung und Lademetern erfassen.',processFlow:['Colli zählen','Verpackung wählen','Maße erfassen','Gewicht erfassen','LDM prüfen'],responsibilities:['Lager/Versand erfassen die tatsächlichen physischen Einheiten.'],prerequisites:['Ware ist verpackt oder Verpackungsplanung ist eindeutig.'],resources:['ExportHUB Colli-Erfassung','Waage','Maßangaben'],steps:['Tatsächliche Verpackungseinheiten der Sendung zählen.','Für jede Position die richtige Verpackungsart wählen.','Physische Anzahl eintragen; drei Europaletten werden als Anzahl 3 erfasst.','Gewicht der Position erfassen und auf Plausibilität prüfen.','Länge, Breite und Höhe erfassen, soweit für Transport oder Dokumente erforderlich.','Lademeter gemäß gültiger Berechnung erfassen; soweit keine abweichende Vorgabe gilt, werden 0,20 LDM je physische Palette verwendet.','Gesamtdaten mit der bereitgestellten Ware vergleichen.','Erst nach Plausibilitätsprüfung Versanddokumente erzeugen.'],checks:['Anzahl entspricht physischen Einheiten.','Gewicht und Maße sind plausibel.','LDM berücksichtigt die physische Palettenanzahl.'],deviations:['Kundenspezifische Verpackungsregeln werden gemäß SOP XXXX angewendet.'],records:['Colli-Datensatz','Gewicht und Abmessungen'],metrics:['Korrekturen der Colli-Daten nach Dokumenterstellung'],relatedDocuments:['SOP-LOG-006 – Versanddokumente'],references:['SOP-LOG-006']}),

  define({number:'SOP-LOG-004',title:'Priorisierung und Urgent Orders',area:'Versand und Export',keywords:['Urgent','P0','P1','P2','P3','P4','Express'],processOwner:'Versandkoordination',scope:'Zeitkritische und normale Versandaufträge',purpose:'Versandaufträge nach einer einheitlichen Prioritätslogik bearbeiten und drohende Terminüberschreitungen früh erkennen.',processFlow:['Priorität bestimmen','Deadline prüfen','Bearbeiten','Risiko melden','Versand freigeben'],responsibilities:['Versandkoordination priorisiert offene Vorgänge.','Mitarbeiter melden absehbare Terminrisiken frühzeitig.'],prerequisites:['Prioritätsstufe und Versandbedarf sind bekannt.'],resources:['ExportHUB Aufgaben','Versandauftrag','Transportinformation'],steps:['Priorität des Auftrags bestimmen.','P0 Sondertransport mit höchster Priorität und Zielzeit bis 13:00 Uhr bearbeiten.','P1 Express mit erforderlicher Versandbestätigung direkt nach P0 bearbeiten.','P2 Express nach Wareneingang bis spätestens 14:30 Uhr bearbeiten.','P3 Express Versand bis spätestens 15:30 Uhr bearbeiten.','P4 Normalversand entsprechend Kapazität grundsätzlich bis spätestens 15:30 Uhr bearbeiten.','Vor Ablauf der Zielzeit prüfen, ob Ware, Dokumente und Transport verfügbar sind.','Drohende Überschreitung unverzüglich an die zuständige Koordination melden.','Bei Sondertransport erforderliche Freigabe einholen.'],checks:['Priorität ist im Arbeitsvorrat erkennbar.','Terminrisiko wird vor Fristablauf gemeldet.'],deviations:['Buchung eines externen Sondertransportes erfolgt gemäß SOP XXXX.'],records:['Priorität','Bearbeitungs-/Statuszeitpunkte'],metrics:['Termintreue je Prioritätsstufe'],relatedDocuments:['SOP-LOG-005 – Versandart, Spedition und Versandkosten'],references:['SOP-LOG-005']}),

  define({number:'SOP-LOG-005',title:'Versandart, Spedition und Versandkosten',area:'Versand und Export',keywords:['Spedition','UPS','Gate41','Versandkosten','Maut'],processOwner:'Versand',scope:'Auswahl und Kostenprüfung von Transportdienstleistungen',purpose:'Eine geeignete Versandart auswählen und Transportkosten plausibel, vollständig und nachvollziehbar ermitteln.',processFlow:['Anforderungen prüfen','Dienstleister wählen','Preis ermitteln','Plausibilisieren','Buchen'],responsibilities:['Versand wählt den geeigneten Dienstleister innerhalb der geltenden Vorgaben.'],prerequisites:['Zielland, Colli, Gewicht, Maße und gewünschte Laufzeit sind bekannt.'],resources:['ExportHUB Versandkosten','UPS','Gate41','Speditionsangebote'],steps:['Zielland und gewünschte Laufzeit prüfen.','Gewicht, Abmessungen, Colli und gegebenenfalls LDM prüfen.','Kunden- oder Routenvorgaben berücksichtigen.','Geeigneten Transportdienstleister bestimmen.','Versandpreis über die vorgesehene Preisquelle ermitteln.','Maut, Zuschläge und weitere bekannte Kostenbestandteile berücksichtigen.','Preis auf Plausibilität prüfen; 0,00 EUR oder fehlende Werte nicht ungeprüft akzeptieren.','Transportentscheidung dokumentieren und Buchung durchführen.'],checks:['Preis ist vorhanden und plausibel.','Zielland wurde korrekt erkannt.','Transport passt zu Laufzeit und Sendungsdaten.'],deviations:['UPS-Buchung erfolgt gemäß SOP XXXX.','Gate41-Bedienung erfolgt gemäß SOP XXXX.','Sonstige Speditionsportale werden gemäß SOP XXXX bedient.'],records:['Versandart','Dienstleister','Preis-/Kosteninformation','Buchungsreferenz'],metrics:['Kostenabweichungen','Fehlende Preisermittlungen'],relatedDocuments:['SOP-LOG-003 – Verpackung, Colli, Gewicht und LDM'],references:['SOP-LOG-003']}),

  define({number:'SOP-LOG-006',title:'Versanddokumente',area:'Versand und Export',keywords:['Lieferschein','L1','L2','Dokumente','CMR','ABD'],processOwner:'Versand / Export',scope:'Pflichtdokumente einer Sendung',purpose:'Sicherstellen, dass vor Versand alle für den konkreten Versandfall erforderlichen Dokumente vollständig und korrekt vorhanden sind.',processFlow:['Versandfall prüfen','Pflichtdokumente bestimmen','Erstellen/hochladen','Kontrollieren','Freigeben'],responsibilities:['Versand erstellt und kontrolliert die Dokumente.','Export stellt erforderliche Zolldokumente bereit.'],prerequisites:['Sendungs- und Colli-Daten sind geprüft.'],resources:['Lieferschein','Deckblatt','L1 / QR','L2','CMR','ABD','POD'],steps:['Sendungsdaten vor Dokumenterstellung erneut prüfen.','Standardpflichtdokumente Lieferschein, Deckblatt, L1 / QR und L2 bestimmen.','Bei Auslandssendungen prüfen, ob CMR erforderlich ist.','Bei ABD-pflichtiger Sendung den ABD-Status gemäß SOP-LOG-007 prüfen.','Dokumente erzeugen beziehungsweise erhaltene Dokumente hochladen.','Jedes Dokument auf Lesbarkeit, Empfängerbezug und wesentliche Sendungsdaten kontrollieren.','Dokument eindeutig der richtigen Sendung zuordnen.','Vollständigkeit vor Versandfreigabe prüfen.','Fehlendes Pflichtdokument nachfordern und Versand gegebenenfalls sperren.','Nach Abholung den erforderlichen POD gemäß SOP-LOG-012 ergänzen.'],checks:['Keine leeren oder unlesbaren Pflichtdokumente.','Dokument gehört zur richtigen Sendung.'],deviations:['Fehlende versandsperrende Dokumente dürfen nicht durch manuelle Statusänderung umgangen werden.'],records:['Dokumentenliste je Sendung','Dokumentdateien'],metrics:['Sendungen mit fehlendem Pflichtdokument'],relatedDocuments:['SOP-LOG-007 – ABD und Zollabwicklung','SOP-LOG-008 – CMR','SOP-LOG-009 – Ladeliste und Gesamtdruck','SOP-LOG-012 – POD und Abliefernachweis'],references:['SOP-LOG-007','SOP-LOG-008','SOP-LOG-009','SOP-LOG-012']}),

  define({number:'SOP-LOG-007',title:'ABD und Zollabwicklung',area:'Versand und Export',keywords:['ABD','Zoll','Nicht-EU','Ausfuhr'],processOwner:'Export',scope:'Nicht-EU-Sendungen und weitere ABD-pflichtige Versandfälle',purpose:'ABD-Pflicht korrekt bestimmen und verhindern, dass eine zollpflichtige Sendung ohne erforderliches Ausfuhrbegleitdokument versendet wird.',processFlow:['Zielland prüfen','ABD-Pflicht bestimmen','Anfordern','Warten','Dokument prüfen','Freigeben'],responsibilities:['Export bestimmt die ABD-Pflicht und koordiniert die Zollanmeldung.','Versand beachtet den Status „Wartet auf ABD“ als Versandsperre.'],prerequisites:['Zielland, Warenwert und Speditionsanforderung sind bekannt.'],resources:['ExportHUB ABD-Bereich','Rechnung/Warenwert','Lieferschein','Zollsystem'],steps:['Zielland prüfen und EU-/Nicht-EU-Status feststellen.','Bei Nicht-EU-Sendung Warenwert prüfen.','Prüfen, ob Warenwert über 1.000 EUR liegt oder die Spedition ein ABD verlangt.','Weitere rechtliche beziehungsweise interne ABD-Vorgaben berücksichtigen.','Bei ABD-Pflicht erforderliche Unterlagen zusammenstellen.','ABD beziehungsweise Zollanmeldung anfordern und Sendungsstatus auf „Wartet auf ABD“ setzen.','Solange das erforderliche ABD fehlt, keine Versandfreigabe erteilen.','Erhaltenes ABD der richtigen Sendung zuordnen und Referenz prüfen.','Bei mehreren ABD alle zugehörigen Dokumente hinterlegen.','Nach erfolgreicher Prüfung Versandsperre aufheben und Folgeprozess fortsetzen.'],checks:['ABD-Pflicht ist nachvollziehbar entschieden.','Bei Pflicht ist Dokument vorhanden und der Sendung zugeordnet.'],deviations:['Die eigentliche Zollanmeldung beziehungsweise Bedienung des externen Zollsystems erfolgt gemäß SOP XXXX.'],records:['ABD-Anfrage','ABD-Datei','Referenz','Statuszeitpunkte'],metrics:['Sendungen „Wartet auf ABD“','ABD-bedingte Verzögerungen'],relatedDocuments:['SOP-LOG-006 – Versanddokumente','SOP-LOG-010 – Bereitstellung zur Abholung'],references:['SOP-LOG-006','SOP-LOG-010']}),

  define({number:'SOP-LOG-008',title:'CMR',area:'Versand und Export',keywords:['CMR','Frachtbrief','Transportdokument'],processOwner:'Versand',scope:'Sendungen mit erforderlichem CMR-Frachtbrief',purpose:'CMR mit den korrekten Absender-, Empfänger-, Waren- und Colli-Daten erstellen.',processFlow:['Daten prüfen','CMR erzeugen','Inhalt kontrollieren','Bereitstellen'],responsibilities:['Versand erstellt und kontrolliert den CMR.'],prerequisites:['Empfänger-, Colli- und Gewichtsdaten sind freigegeben.'],resources:['ExportHUB CMR','Sendungsdaten'],steps:['Absenderdaten prüfen.','Empfänger und Ablieferstelle prüfen.','Colli-Anzahl und Verpackungsart mit der tatsächlichen Sendung vergleichen.','Warenbeschreibung prüfen und vollständig eintragen.','Gewicht und erforderliche Transportangaben kontrollieren.','CMR erzeugen.','Erzeugten CMR vor Verwendung vollständig lesen und auf falsche Fremddaten prüfen.','Freigegebenen CMR den Versandunterlagen zuordnen.'],checks:['Keine Daten einer anderen Sendung enthalten.','Colli und Gewicht stimmen mit Versanddaten überein.'],deviations:['Änderungen nach Abholung nur über den geregelten Korrekturprozess gemäß SOP-QM-003 durchführen.'],records:['CMR-Datei','zugehörige Sendungsnummer'],metrics:['CMR-Korrekturen nach Erstellung'],relatedDocuments:['SOP-LOG-003 – Verpackung, Colli, Gewicht und LDM','SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-LOG-003','SOP-QM-003']}),

  define({number:'SOP-LOG-009',title:'Ladeliste und Gesamtdruck',area:'Versand und Export',keywords:['Ladeliste','Gesamtdruck','QR','PDF'],processOwner:'Versand',scope:'Ausgabe der vollständigen Versandunterlagen',purpose:'Ladeliste und Gesamtdruck vollständig und fehlerfrei erzeugen und dabei QR-/PDF-Regeln einhalten.',processFlow:['Daten prüfen','Ladeliste erzeugen','Gesamtdruck erzeugen','Seiten prüfen','Freigeben'],responsibilities:['Versand prüft die erzeugten Ausgabedokumente vor Verwendung.'],prerequisites:['Sendung und erforderliche Dokumente sind vollständig erfasst.'],resources:['ExportHUB Gesamtdruck','Ladeliste','Drucker/PDF'],steps:['Sendung, Colli und Dokumentstatus prüfen.','Ladeliste mit den vorgesehenen Sendungs- und Verpackungsdaten erzeugen.','QR-Code ausschließlich an der dafür vorgesehenen Stelle der ersten gedruckten Ladeliste verwenden.','Gesamtdruck starten.','Alle erzeugten Seiten auf Inhalt, Zuordnung und Lesbarkeit prüfen.','Leere oder unvollständige L1-, L2-, CMR- oder sonstige Pflichtseiten nicht verwenden.','Bei Fehler Ausgabe stoppen, Ursache korrigieren und Dokumente neu erzeugen.','Geprüfte Druckunterlagen für die Übergabe bereitstellen.'],checks:['Keine leeren Pflichtseiten.','QR-Regel wird eingehalten.','Dokumente gehören zur aktuellen Sendung.'],deviations:['Technischer Druckfehler wird gemäß SOP-SYS-002 behandelt.'],records:['Erzeugte Versanddokumente','Ausgabestatus'],metrics:['Fehlerhafte Druckvorgänge'],relatedDocuments:['SOP-LOG-006 – Versanddokumente','SOP-LOG-011 – QR-Abholung und Verlade-PIN'],references:['SOP-LOG-006','SOP-LOG-011']}),

  define({number:'SOP-LOG-010',title:'Bereitstellung zur Abholung',area:'Versand und Export',keywords:['Bereit zur Abholung','Freigabe','Abholung'],processOwner:'Versand / Lager',scope:'Sendungen vor physischer Übergabe',purpose:'Nur vollständig vorbereitete und freigegebene Sendungen als „Bereit zur Abholung“ kennzeichnen.',processFlow:['Ware prüfen','Dokumente prüfen','Sperren prüfen','Bereitstellen','Status setzen'],responsibilities:['Lager stellt Ware physisch bereit.','Versand prüft Dokumente und Versandsperren.'],prerequisites:['Sendung ist erstellt und Ware verfügbar.'],resources:['ExportHUB Sendungsstatus','Versandunterlagen'],steps:['Prüfen, ob die Ware vollständig und am vorgesehenen Abholplatz verfügbar ist.','Tatsächliche Colli-Anzahl mit ExportHUB vergleichen.','Pflichtdokumente gemäß SOP-LOG-006 auf Vollständigkeit prüfen.','Bei ABD-Pflicht prüfen, ob das ABD vorhanden und freigegeben ist.','Offene versandsperrende Abweichungen prüfen.','Abholdaten beziehungsweise geplanten Abholtag prüfen.','Ware und Unterlagen eindeutig der Sendung zuordnen.','Erst nach erfolgreicher Gesamtprüfung den Status „Bereit zur Abholung“ setzen.'],checks:['Ware vollständig.','Keine aktive Versandsperre.','Pflichtdokumente vollständig.'],deviations:['Bei fehlender Voraussetzung Status nicht setzen; Abweichung nach SOP-QM-003 behandeln.'],records:['Statuszeitpunkt „Bereit zur Abholung“','Prüf-/Dokumentenstatus'],metrics:['Sendungen mit zurückgenommener Bereitstellung'],relatedDocuments:['SOP-LOG-006 – Versanddokumente','SOP-LOG-007 – ABD und Zollabwicklung','SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-LOG-006','SOP-LOG-007','SOP-QM-003']}),

  define({number:'SOP-LOG-011',title:'QR-Abholung und Verlade-PIN',area:'Versand und Export',keywords:['QR','Abholung','PIN','Colli','Fahrer'],processOwner:'Versand / Verladung',scope:'Fahrer- und Selbstabholprozesse mit ExportHUB QR-Abholung',purpose:'Abholungen eindeutig, sicher und mit tatsächlicher Colli-Anzahl, Zeitpunkt und Verlade-PIN bestätigen.',processFlow:['QR-Code öffnen','Sendung prüfen','Verlade-PIN prüfen','Colli bestätigen','Abholung abschließen'],responsibilities:['Verladepersonal stellt die richtige Sendung bereit.','Abholer bestätigt die vorgesehenen Daten.','Versand überwacht den korrekten Abschluss.'],prerequisites:['Sendung besitzt Status „Bereit zur Abholung“.','Gültiger QR-Zugang und Verlade-PIN stehen für den Vorgang zur Verfügung.'],resources:['Ladeliste mit QR','ExportHUB Abholseite','Verlade-PIN'],steps:['QR-Code der aktuellen Sendung scannen beziehungsweise den vorgesehenen sicheren Abholzugang öffnen.','Prüfen, ob die angezeigte Referenz und Empfängeradresse zur bereitgestellten Sendung gehören.','Erforderliche Fahrer-/Speditionsangaben gemäß Abholmaske erfassen.','Verlade-PIN eingeben und Systemprüfung abwarten.','Soll-Colli mit der physisch übergebenen Anzahl vergleichen.','Bei Teilabholung nur die tatsächlich übergebene Colli-Anzahl bestätigen; Restmenge muss nachvollziehbar offen bleiben.','Erforderliche Bestätigung beziehungsweise Unterschrift erfassen.','Abholung abschließen und kontrollieren, ob Datum/Uhrzeit sowie Status korrekt gespeichert wurden.','Nach vollständiger Abholung muss der Sendungsstatus „Abgeholt“ anzeigen.','Ab „Abgeholt“ dürfen versandrelevante Kerndaten nicht normal nachträglich verändert werden.'],checks:['QR gehört zur aktuellen Sendung.','PIN ist gültig.','Ist-Colli entspricht der tatsächlichen Übergabe.','Status und Zeitstempel wurden gespeichert.'],deviations:['Bei ungültigem QR oder PIN keine ungeprüfte manuelle Bestätigung durchführen. Notfallverfahren erfolgt gemäß SOP XXXX.','Systemfehler gemäß SOP-SYS-002 behandeln.'],records:['Abholzeitpunkt','bestätigte Colli','Fahrer-/Speditionsdaten','Unterschrift/POD-Daten soweit vorgesehen'],metrics:['Fehlgeschlagene PIN-Prüfungen','Teilabholungen','Abholfehler'],relatedDocuments:['SOP-LOG-010 – Bereitstellung zur Abholung','SOP-LOG-012 – POD und Abliefernachweis','SOP-SYS-002 – Fehler und Systemstörungen'],references:['SOP-LOG-010','SOP-LOG-012','SOP-SYS-002']}),

  define({number:'SOP-LOG-012',title:'POD und Abliefernachweis',area:'Versand und Export',keywords:['POD','Abliefernachweis','Unterschrift'],processOwner:'Versand',scope:'Abliefer- und Abholnachweise nach Versand',purpose:'POD-Dokumente eindeutig der richtigen Sendung zuordnen, auf Lesbarkeit prüfen und für den Sendungsabschluss sichern.',processFlow:['POD erhalten','Sendung identifizieren','Inhalt prüfen','Hochladen','Status aktualisieren'],responsibilities:['Versand ordnet den POD der richtigen Sendung zu und prüft ihn.'],prerequisites:['Abholung beziehungsweise Lieferung ist erfolgt.'],resources:['ExportHUB Dokumente','POD-Datei'],steps:['POD erhalten oder automatisiert übernehmen.','Sendung anhand Referenz, Empfänger oder anderer eindeutiger Merkmale identifizieren.','Ablieferdatum und Empfänger/Ablieferstelle prüfen.','Dokument auf Lesbarkeit und verwertbaren Nachweis prüfen.','POD der richtigen Sendung hochladen beziehungsweise bestätigen.','Bei sachlich erforderlichen mehreren POD-Dokumenten alle zugehörigen Nachweise ablegen.','Status auf „POD vorhanden“ setzen beziehungsweise automatische Statusänderung kontrollieren.','POD für den Abschluss gemäß SOP-LOG-017 berücksichtigen.'],checks:['POD gehört eindeutig zur Sendung.','Dokument ist lesbar.'],deviations:['POD einer anderen Sendung niemals übernehmen. Bei unklarem Dokument Klärung vor Statusänderung durchführen.'],records:['POD-Datei','Upload-/Statuszeitpunkt'],metrics:['Sendungen ohne POD','POD-Nachforderungsdauer'],relatedDocuments:['SOP-LOG-017 – Abschluss und Archivierung einer Sendung'],references:['SOP-LOG-017']}),

  define({number:'SOP-LOG-013',title:'Palettenkonto',area:'Versand und Export',keywords:['Palettenkonto','Europalette','Eingang','Ausgang','Tausch'],processOwner:'Versand / Lager',scope:'Buchungen von Europaletten',purpose:'Ein- und Ausgänge von Europaletten nachvollziehbar buchen und Doppel- oder Fehlbuchungen verhindern.',processFlow:['Partner wählen','Bewegungsart wählen','Anzahl erfassen','Buchen','Kontrollieren'],definitions:['Palettenkonto: Saldenführung ausschließlich für die dafür vorgesehenen Europalettenbewegungen.'],responsibilities:['Lager/Versand buchen tatsächliche Bewegungen.','Administratoren führen nur begründete Ausgleichsbuchungen durch.'],prerequisites:['Geschäftspartner und tatsächliche Palettenanzahl sind bekannt.'],resources:['ExportHUB Palettenkonto'],steps:['Kunde beziehungsweise Geschäftspartner auswählen.','Bewegungsart Eingang oder Ausgang wählen.','Tatsächliche Anzahl Europaletten eintragen.','Optional vorhandene Referenz erfassen; eine Referenznummer ist für normalen Eingang oder Ausgang kein Pflichtfeld.','Bei Ausgang gegebenenfalls den vorgesehenen QR-/Sendungsbezug verwenden.','Bei Eingang Tausch kennzeichnen, wenn tatsächlich ein Tausch stattgefunden hat.','Buchung ausführen.','Neu entstandenen Saldo und Buchungseintrag kontrollieren.','Fehlbuchung nicht durch zweite Gegenbuchung ohne Begründung verschleiern; geregelte Korrektur verwenden.'],checks:['Anzahl ist größer als null und plausibel.','Keine unbeabsichtigte Doppelbuchung.','Buchung funktioniert ohne Referenz.'],deviations:['Administrative Ausgleichsbuchung nur durch berechtigte Person und mit Begründung.'],records:['Palettenbuchung','Saldo','Benutzer-/Zeitstempel'],metrics:['Korrekturbuchungen','offene Palettensalden'],relatedDocuments:['SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-QM-003']}),

  define({number:'SOP-LOG-014',title:'Kundenavis',area:'Versand und Export',keywords:['Avis','Kundenlink','Dokumente','Einmal-Link'],processOwner:'Versand',scope:'Sichere Bereitstellung freigegebener Sendungsinformationen an Kunden',purpose:'Kunden ausschließlich die für ihren Versandfall freigegebenen Informationen über einen sicheren persönlichen Avis-Zugang bereitstellen.',processFlow:['Sendung wählen','Inhalt freigeben','Link erzeugen','Versenden','Zugriff beenden'],responsibilities:['Versand entscheidet, welche Informationen freigegeben werden.','System schützt den Zugriff gegen andere Kunden- oder Firmendaten.'],prerequisites:['Sendung und zulässiger Empfänger sind eindeutig.'],resources:['ExportHUB Kundenavis','E-Mail'],steps:['Betroffene Sendung auswählen.','Prüfen, welche Sendungsdaten und Dokumente für den Kunden freigegeben werden dürfen.','Kundenavis aktivieren.','Sicheren persönlichen Zugriff erzeugen und vorgesehene Gültigkeit anwenden.','Avis an den vorgesehenen Empfänger versenden.','Sicherstellen, dass der Link ausschließlich die freigegebenen Daten der zugehörigen Sendung anzeigt.','Bei Einmal-Link nach erfolgreicher Erstautorisierung keine erneute Nutzung des Rohlinks zulassen.','Bei Bedarf Zugriff vorzeitig deaktivieren beziehungsweise neu ausstellen; alter Zugriff muss ungültig werden.','POD nur anzeigen, wenn er für diesen Avis freigegeben und vorhanden ist.'],checks:['Keine Daten anderer Kunden oder Firmen sichtbar.','Nur freigegebene Dokumente werden angeboten.'],deviations:['Versand der Benachrichtigungs-E-Mail beziehungsweise externe Mailbedienung erfolgt gemäß SOP XXXX.'],records:['Avis-Ausstellung','Gültigkeit/Deaktivierung','Kundenbestätigung soweit vorgesehen'],metrics:['Fehlgeschlagene Avis-Zugriffe','neu ausgestellte Avis-Links'],relatedDocuments:['SOP-SYS-001 – Benutzer, Rollen und Zugriffsrechte','SOP-LOG-012 – POD und Abliefernachweis'],references:['SOP-SYS-001','SOP-LOG-012']}),

  define({number:'SOP-LOG-015',title:'Selbstabholer',area:'Versand und Export',keywords:['Selbstabholer','Abholtermin','Übergabe'],processOwner:'Versand / Verladung',scope:'Kunden- oder beauftragte Selbstabholungen',purpose:'Selbstabholungen geplant, eindeutig und nach denselben Übergabe- und Nachweisregeln wie andere Abholungen durchführen.',processFlow:['Termin erfassen','Ware vorbereiten','Abholer prüfen','Übergabe','Status aktualisieren'],responsibilities:['Versand koordiniert Termin und Dokumente.','Lager stellt die richtige Ware bereit.'],prerequisites:['Abholsendung und Termin sind bekannt.'],resources:['ExportHUB Abholkalender','Versandunterlagen','QR-Abholung'],steps:['Geplante Selbstabholung mit Kunde, Sendung und Termin erfassen.','Vor Termin Waren- und Dokumentstatus prüfen.','Ware eindeutig im vorgesehenen Bereich bereitstellen.','Bei Erscheinen des Abholers Sendung und erforderliche Abholberechtigung prüfen.','Tatsächliche Colli-Anzahl mit dem System vergleichen.','Übergabe gemäß SOP-LOG-011 durchführen und bestätigen.','Sendungsstatus nach erfolgreicher Übergabe kontrollieren.','Abweichende oder nicht erfolgte Abholung im Abholkalender beziehungsweise Vorgang dokumentieren.'],checks:['Abholer erhält die richtige Sendung.','Tatsächliche Colli sind bestätigt.'],deviations:['Unklare Abholberechtigung oder falsche Referenz vor Übergabe klären; Ware nicht ungeprüft herausgeben.'],records:['Abholtermin','Übergabenachweis','Statuszeitpunkt'],metrics:['Nicht erfolgte Selbstabholungen','Terminabweichungen'],relatedDocuments:['SOP-LOG-011 – QR-Abholung und Verlade-PIN'],references:['SOP-LOG-011']}),

  define({number:'SOP-LOG-016',title:'Despatch und Versandübergabe',area:'Versand und Export',keywords:['Despatch','Übergabe','Spedition','Versandsperre'],processOwner:'Versand',scope:'Endkontrolle und Übergabe freigegebener Sendungen',purpose:'Nur vollständig freigegebene Sendungen mit korrekten Dokumenten und ohne aktive Versandsperre an den Transportdienstleister übergeben.',processFlow:['Sendung öffnen','Status prüfen','Dokumente prüfen','Übergeben','Status dokumentieren'],responsibilities:['Despatch/Versand führt die Endkontrolle durch.'],prerequisites:['Sendung ist zur Abholung beziehungsweise zum Versand vorgesehen.'],resources:['ExportHUB','Versanddokumente','Bereitstellungsbereich'],steps:['Sendung eindeutig aufrufen.','Sendungsstatus und geplanten Abholtag prüfen.','Colli mit der bereitgestellten Ware vergleichen.','Pflichtdokumente und bei Bedarf ABD prüfen.','Offene Versandsperren oder Abweichungen prüfen.','Transportdienstleister beziehungsweise Abholer mit dem vorgesehenen Vorgang abgleichen.','Ware und Unterlagen übergeben.','Übergabe beziehungsweise Abholung im vorgesehenen Prozess dokumentieren.','Status und erforderliche Nachweise nach der Übergabe kontrollieren.'],checks:['Keine versandsperrende Abweichung.','Ware, Dokumente und Abholer passen zusammen.'],deviations:['Bei fehlender Voraussetzung keine Übergabe; Vorgang gemäß zuständiger SOP korrigieren.'],records:['Übergabe-/Abholstatus','Versandnachweise'],metrics:['Gestoppte Übergaben wegen fehlender Voraussetzung'],relatedDocuments:['SOP-LOG-010 – Bereitstellung zur Abholung','SOP-LOG-011 – QR-Abholung und Verlade-PIN'],references:['SOP-LOG-010','SOP-LOG-011']}),

  define({number:'SOP-LOG-017',title:'Abschluss und Archivierung einer Sendung',area:'Versand und Export',keywords:['Abschluss','Archiv','Status','POD'],processOwner:'Versand',scope:'Sendungen nach erfolgter Abholung',purpose:'Sendungen erst nach vollständigen Nachweisen abschließen und anschließend nachvollziehbar archivieren.',processFlow:['Abholung prüfen','POD prüfen','Vollständigkeit prüfen','Abschließen','Archivieren'],responsibilities:['Versand prüft Abschlussvoraussetzungen.','System schützt abgeschlossene/archivierte Vorgänge gegen normale Bearbeitung.'],prerequisites:['Sendung wurde abgeholt.'],resources:['ExportHUB Sendungsstatus','Dokumentenübersicht','POD','Palettenkonto'],steps:['Prüfen, ob der Status „Abgeholt“ erreicht wurde.','Erforderlichen POD gemäß SOP-LOG-012 prüfen.','Pflichtdokumente auf Vollständigkeit prüfen.','Offene Abweichungen oder Nachbearbeitungen prüfen.','Erforderliche Palettenbuchung kontrollieren.','Bei vollständigem Vorgang Status „Abgeschlossen“ setzen.','Versandrelevante Kerndaten ab Abschluss gegen normale Änderungen schützen.','Nach vorgesehener Abschlusslogik Vorgang archivieren.','Historische Dokumente und Statusinformationen weiterhin lesbar und nachvollziehbar halten.'],checks:['Abholung und POD vorhanden, sofern erforderlich.','Keine offene versandsperrende Abweichung.'],deviations:['Vorgänge in Nachbearbeitung nicht archivieren, bevor die Abweichung abgeschlossen ist.'],records:['Statushistorie','Archivzeitpunkt','vollständiger Dokumentensatz'],metrics:['Offene Sendungen ohne POD','Durchlaufzeit Abholung bis Abschluss'],relatedDocuments:['SOP-LOG-012 – POD und Abliefernachweis','SOP-LOG-013 – Palettenkonto'],references:['SOP-LOG-012','SOP-LOG-013']}),

  define({number:'SOP-WH-001',title:'Wareneingang',area:'Lager',keywords:['Wareneingang','Menge','Schaden'],processOwner:'Lager / Goods In',scope:'Eingehende Waren und Materialien',purpose:'Eingehende Ware eindeutig identifizieren, Menge und sichtbaren Zustand prüfen und kontrolliert zur Einlagerung weitergeben.',processFlow:['Ware annehmen','Identifizieren','Menge/Zustand prüfen','Buchen','Weitergeben'],responsibilities:['Wareneingang führt Identitäts-, Mengen- und Sichtprüfung durch.'],prerequisites:['Ware und zugehöriger Liefer-/Auftragsbezug liegen vor.'],resources:['Wareneingangsbeleg','ERP/D365','Kennzeichnungsmittel'],steps:['Eingehende Ware dem Lieferanten beziehungsweise Vorgang zuordnen.','Artikel und erwartete Menge prüfen.','Tatsächliche Menge zählen beziehungsweise gemäß Prozess bestimmen.','Verpackung und Ware auf sichtbare Beschädigungen prüfen.','Mengen- oder Schadensabweichung vor normaler Weiterbearbeitung dokumentieren.','Wareneingang im vorgesehenen System buchen.','Ware eindeutig kennzeichnen.','Ware zur vorgesehenen Einlagerung oder Sonderbearbeitung bereitstellen.'],checks:['Artikel und Menge passen zum Beleg.','Beschädigungen sind dokumentiert.'],deviations:['ERP-/D365-Buchung und spezielle Lieferantenprozesse erfolgen gemäß SOP XXXX.'],records:['Wareneingangsbuchung','Abweichungs-/Schadensnachweis'],metrics:['Wareneingangsabweichungen'],relatedDocuments:['SOP-WH-002 – Einlagerung / Putaway','SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-WH-002','SOP-QM-003']}),

  define({number:'SOP-WH-002',title:'Einlagerung / Putaway',area:'Lager',keywords:['Putaway','Einlagerung','Lagerplatz','VNA'],processOwner:'Lager',scope:'Einlagerung freigegebener Ware',purpose:'Ware auf den vorgesehenen, geeigneten Lagerplatz bringen und die Bewegung korrekt im System bestätigen.',processFlow:['Ware identifizieren','Lagerplatz prüfen','Transportieren','Abstellen','Buchen'],responsibilities:['Lager führt Transport und Buchung durch.','Nur qualifizierte Mitarbeiter bedienen erforderliche Flurförderzeuge.'],prerequisites:['Ware ist für die Einlagerung freigegeben und eindeutig gekennzeichnet.'],resources:['ERP/D365','Lagerplatzinformation','Stapler/VNA soweit erforderlich'],steps:['Einzulagernde Ware eindeutig identifizieren.','Artikel und Menge mit dem Einlagerungsauftrag vergleichen.','Vorgesehenen Lagerplatz bestimmen und auf Eignung sowie Verfügbarkeit prüfen.','Erforderliches Flurförderzeug nur mit gültiger Qualifikation verwenden.','Ware sicher zum Lagerplatz transportieren.','Ware ordnungsgemäß und ohne Behinderung anderer Bestände abstellen.','Einlagerung im System buchen.','Gebuchten Lagerplatz und Menge kontrollieren.'],checks:['Physischer und gebuchter Lagerplatz stimmen überein.','Qualifikation für Stapler/VNA ist vorhanden.'],deviations:['Ungeeigneten oder belegten Lagerplatz nicht eigenmächtig als Ersatz buchen; Klärung mit zuständiger Stelle.'],records:['Putaway-Buchung','Lagerplatz'],metrics:['Putaway-Fehlbuchungen'],relatedDocuments:['SOP-QM-002 – Rollen, Verantwortlichkeiten und Qualifikation'],references:['SOP-QM-002']}),

  define({number:'SOP-WH-003',title:'Kommissionierung',area:'Lager',keywords:['Picken','Kommissionierung','Pick','Bestand'],processOwner:'Lager',scope:'Kommissionieraufträge',purpose:'Richtigen Artikel in der richtigen Menge vom richtigen Lagerplatz entnehmen und nachvollziehbar bestätigen.',processFlow:['Auftrag übernehmen','Platz aufsuchen','Artikel/Menge prüfen','Entnehmen','Bestätigen'],responsibilities:['Kommissionierer prüft Artikel, Lagerplatz und Menge vor Bestätigung.'],prerequisites:['Gültiger Arbeitsauftrag ist vorhanden.'],resources:['D365/Arbeitsauftrag','Scanner soweit vorgesehen'],steps:['Arbeitsauftrag übernehmen und Zielauftrag prüfen.','Vorgegebenen Lagerplatz aufsuchen.','Artikelnummer am Lagerplatz mit Auftrag vergleichen.','Benötigte Menge bestimmen und tatsächliche Entnahme zählen.','Nur den bestätigten Artikel in der erforderlichen Menge entnehmen.','Entnahme im System bestätigen.','Ware sicher im vorgesehenen Bereitstellungsbereich abstellen.','Bei Bestands- oder Mengenabweichung nicht durch eine erfundene Buchung ausgleichen, sondern Abweichung melden.'],checks:['Artikelnummer stimmt.','Entnommene Menge stimmt.','Systembestätigung bezieht sich auf dieselbe Position.'],deviations:['Besondere D365-Funktionen und Bestandskorrekturen erfolgen gemäß SOP XXXX.'],records:['Pick-Buchung','Arbeitsauftrag'],metrics:['Pickfehler','Leistung pro Stunde nach SOP-ORG-003'],relatedDocuments:['SOP-QM-003 – Abweichungen und Korrekturmaßnahmen','SOP-ORG-003 – Leistungs- und KPI-Erfassung'],references:['SOP-QM-003','SOP-ORG-003']}),

  define({number:'SOP-WH-004',title:'PPD-Sortierung',area:'Lager',keywords:['PPD','Sortierung','Zuordnung'],processOwner:'Lager / PPD',scope:'PPD-Sortieraufgaben',purpose:'Ware nach der gültigen Zuordnung sortieren und unklare Positionen kontrolliert separieren.',processFlow:['Ware übernehmen','Zuordnung prüfen','Sortieren','Unklares separieren','Abschließen'],responsibilities:['Eingesetzter Mitarbeiter führt Sortierung nach aktueller Zuordnung durch.'],prerequisites:['Sortierauftrag beziehungsweise Zielzuordnung ist bekannt.'],resources:['Sortierinformation','Arbeitsplatz PPD-Sortierung'],steps:['Zu sortierende Ware und Auftrag übernehmen.','Artikel beziehungsweise relevante Kennzeichnung prüfen.','Vorgesehene Zielzuordnung bestimmen.','Ware entsprechend der gültigen Sortierlogik sortieren.','Nicht eindeutig zuordenbare oder auffällige Ware separat kennzeichnen.','Unklare Positionen nicht aufgrund einer Vermutung zuordnen.','Abgeschlossene Sortierung dokumentieren beziehungsweise an Folgeprozess übergeben.'],checks:['Keine unklare Ware wurde ungeprüft zugeordnet.','Sortierbereich bleibt eindeutig getrennt.'],deviations:['Unklare Zuordnung an zuständige Führungskraft/Prozessverantwortlichen melden.'],records:['Arbeits-/Leistungsnachweis soweit vorgesehen'],metrics:['PPD-Sortierung Sollwert 80','Fehlzuordnungen'],relatedDocuments:['SOP-ORG-002 – Schicht- und Personaleinsatzplanung','SOP-ORG-003 – Leistungs- und KPI-Erfassung'],references:['SOP-ORG-002','SOP-ORG-003']}),

  define({number:'SOP-WH-005',title:'Reform / Rework',area:'Lager',keywords:['Rework','Reform','Nacharbeit','Ausschuss'],processOwner:'Lager / Rework',scope:'Freigegebene Nacharbeitsaufträge',purpose:'Nacharbeiten ausschließlich nach eindeutiger Vorgabe durchführen und Ergebnis, Mengen sowie Ausschuss nachvollziehbar behandeln.',processFlow:['Auftrag prüfen','Nacharbeit bestimmen','Ausführen','Kontrollieren','Abschließen'],responsibilities:['Rework-Mitarbeiter führen nur die freigegebene Nacharbeit aus.'],prerequisites:['Rework-Auftrag und Bearbeitungsanforderung sind eindeutig.'],resources:['Rework-Auftrag','produktspezifische Anweisung','Arbeitsmittel'],steps:['Rework-Auftrag und betroffenen Artikel identifizieren.','Grund und gewünschtes Ergebnis der Nacharbeit prüfen.','Erforderliche Arbeitsschritte anhand der freigegebenen Vorgabe bestimmen.','Nur die beschriebenen Bearbeitungen durchführen.','Bearbeitete Menge und gegebenenfalls Ausschuss getrennt erfassen.','Ergebnis auf die geforderte Ausführung prüfen.','Freigegebene Ware in den vorgesehenen Folgeprozess geben.','Auftrag mit tatsächlichem Ergebnis abschließen.'],checks:['Nacharbeit entspricht der freigegebenen Vorgabe.','Ausschuss wird nicht mit Gutmenge vermischt.'],deviations:['Produktspezifische Rework-Anweisung erfolgt gemäß SOP XXXX.'],records:['Rework-Auftrag','Mengen-/Ergebnisnachweis'],metrics:['Rework-Menge','Ausschussquote'],relatedDocuments:['SOP-QM-003 – Abweichungen und Korrekturmaßnahmen'],references:['SOP-QM-003']}),

  define({number:'SOP-WH-006',title:'DAF Area',area:'Lager',keywords:['DAF','Bereitstellung','Lagerplatz'],processOwner:'Lager / DAF',scope:'Ware im DAF-Bereich',purpose:'DAF-Ware eindeutig, geordnet und systemisch nachvollziehbar an den vorgesehenen Plätzen führen.',processFlow:['Ware identifizieren','DAF-Ziel prüfen','Abstellen','Buchen','Kontrollieren'],responsibilities:['DAF-Verantwortliche beziehungsweise eingesetzte Mitarbeiter halten Platz- und Buchungslogik ein.'],prerequisites:['Ware ist eindeutig als DAF-relevant identifiziert.'],resources:['DAF-Bereich','Lager-/Arbeitsübersicht'],steps:['Ware eindeutig identifizieren und DAF-Zuordnung prüfen.','Vorgesehenen DAF-Platz bestimmen.','Ware ausschließlich am vorgesehenen Platz abstellen.','Ware nicht ohne Buchung oder nachvollziehbare Übergabe in einen anderen Bereich verschieben.','Standort beziehungsweise Bewegung im vorgesehenen System erfassen.','Bei unklarem oder belegtem Platz zuständige Person informieren.','Abgeschlossene Bewegung kontrollieren.'],checks:['Ware steht am gebuchten/vorgesehenen Platz.','Keine unmarkierte Zwischenablage.'],deviations:['Spezielle DAF-Prozessanforderungen erfolgen gemäß SOP XXXX.'],records:['Standort-/Bewegungsnachweis'],metrics:['Fehlplatzierungen im DAF-Bereich'],relatedDocuments:['SOP-WH-002 – Einlagerung / Putaway'],references:['SOP-WH-002']}),

  define({number:'SOP-WH-007',title:'Lager-Arbeitsliste und Minibag-Analyse',area:'Lager',keywords:['Arbeitsliste','Minibag','Open sales order lines','On-hand','Packing quantity'],processOwner:'Lagerplanung',scope:'Analyse offener Lagerarbeit und Minibag-/Mengenanpassungen',purpose:'Offene Lagerarbeiten aus definierten Reports systematisch ermitteln, priorisieren und nachvollziehbar abarbeiten.',processFlow:['Reports laden','Daten zuordnen','Abweichungen berechnen','Arbeitsliste erstellen','Abarbeiten'],responsibilities:['Lagerplanung erstellt die Analyse.','Lager arbeitet die freigegebene Liste ab und dokumentiert Ergebnisse.'],prerequisites:['Aktuelle Reports Open Sales Order Lines und Physical On-hand Inventory stehen zur Verfügung.','Packing-Quantity-Zuordnung ist verfügbar.'],resources:['Open Sales Order Lines','Physical on-hand inventory','Packing-Quantity-Matrix','ExportHUB/Excel-Auswertung'],steps:['Aktuellen Report „Open Sales Order Lines“ für den benötigten Ship-Date-Zeitraum bereitstellen.','Aktuellen Report „Physical on-hand inventory“ bereitstellen.','Sales Order, Item Number und Deliver Remainder eindeutig übernehmen.','Packing Quantity über die gültige Zuordnungsmatrix ergänzen.','Datensätze über eindeutige Artikel-/Auftragslogik zusammenführen.','Positionen ermitteln, deren Menge keine vollständige Verpackungseinheit bildet, und Report „Menge anpassen“ erzeugen.','Positionen unterhalb der definierten Minibag-Menge bestimmen und Report „< Minibag“ erzeugen.','Aus den relevanten Positionen eine priorisierte Lager-Arbeitsliste erstellen.','Arbeitsliste im Lager abarbeiten und Ergebnisse aktualisieren.','Unklare Zuordnungen vor Bearbeitung klären und nicht automatisch schätzen.'],checks:['Pflichtspalten Sales Order, Item Number, Deliver Remainder und Packing Quantity vorhanden.','Reports stammen aus demselben aktuellen Datenstand beziehungsweise Abweichung ist bekannt.'],deviations:['Erstellung und Export der D365-Reports erfolgt gemäß SOP XXXX.'],records:['Analyseausgabe','Arbeitsliste','Bearbeitungsstatus'],metrics:['Offene Positionen','Abgearbeitete Positionen','Alter der offenen Arbeitsliste'],relatedDocuments:['SOP-WH-003 – Kommissionierung'],references:['SOP-WH-003']}),

  define({number:'SOP-ORG-001',title:'Aufgabenplanung, Urlaub und Vertretung',area:'Organisation',keywords:['Aufgabe','Urlaub','Vertretung','Wiederholung','Erinnerung'],processOwner:'Führungskraft / Aufgabenverantwortlicher',scope:'Operative Aufgaben und Vertretungsplanung in ExportHUB',purpose:'Aufgaben eindeutig zuordnen, Abwesenheiten berücksichtigen und wiederkehrende Arbeiten termingerecht neu bereitstellen.',processFlow:['Aufgabe planen','Verfügbarkeit prüfen','Zuweisen','Bearbeiten','Abschließen/Wiederholen'],responsibilities:['Aufgabenverantwortliche planen Aufgaben und Vertretung.','Mitarbeiter aktualisieren den tatsächlichen Bearbeitungsstatus.'],prerequisites:['Aufgabe, Fälligkeit und Verantwortungsbereich sind bekannt.'],resources:['ExportHUB Aufgaben','Urlaubsübersicht','Vertretungsinformation'],steps:['Aufgabe manuell anlegen oder automatisch erzeugte Aufgabe prüfen.','Verantwortungsbereich, Fälligkeit und Priorität festlegen.','Verfügbarkeit des vorgesehenen Mitarbeiters anhand Urlaub/Abwesenheit prüfen.','Bei Abwesenheit eine geeignete Vertretung zuordnen.','Aufgabe dem verantwortlichen Mitarbeiter sichtbar zuweisen.','Erforderliche Erinnerungen entsprechend der Aufgabe verwenden; vorgesehene Standardzeitpunkte können 09:00, 12:00 und 15:00 Uhr sein.','Aufgabe durchführen und erforderlichen Nachweis hinterlegen.','Aufgabe erst nach tatsächlicher Durchführung als erledigt markieren beziehungsweise durch die zugehörige Website-Aktion automatisch erledigen lassen.','Bei wiederkehrender Aufgabe die nächste Periode als eigenständige Aufgabe erzeugen; der erledigte Status der Vorperiode darf nicht übernommen werden.'],checks:['Urlaub/Vertretung wurde berücksichtigt.','Wiederholungsaufgaben besitzen eindeutige Periodenidentität.'],deviations:['Nicht lösbare Kapazitätskonflikte an die zuständige Führungskraft eskalieren.'],records:['Aufgabenstatus','Zuweisung','Fälligkeit','Erledigungsnachweis'],metrics:['Überfällige Aufgaben','Erledigungsquote'],relatedDocuments:['SOP-ORG-002 – Schicht- und Personaleinsatzplanung'],references:['SOP-ORG-002']}),

  define({number:'SOP-ORG-002',title:'Schicht- und Personaleinsatzplanung',area:'Organisation',keywords:['Schicht','Personal','Skillmatrix','PPD','AS picken'],processOwner:'Lagerführung',scope:'Tägliche und wöchentliche Personaleinsatzplanung',purpose:'Mitarbeiter entsprechend Verfügbarkeit, Qualifikation, Fixzuordnung und Kapazitätsbedarf sicher auf die Lagerbereiche verteilen.',processFlow:['Personal prüfen','Bedarf bestimmen','Skills prüfen','Einteilen','Plan kontrollieren'],definitions:['Frühschicht: 06:00–14:30.','Tagschicht: 08:00–16:30.','Spätschicht: 10:00–18:30.'],responsibilities:['Lagerführung erstellt und aktualisiert die Einsatzplanung.'],prerequisites:['Anwesenheit/Urlaub und Skillmatrix sind aktuell.','Arbeitsvolumen beziehungsweise Bereichsbedarf ist bekannt.'],resources:['Schichtplan','Urlaubsübersicht','Skillmatrix','KPI-/Leistungsdaten'],steps:['Verfügbares Personal je Schicht bestimmen.','Urlaub, Krankheit und sonstige Abwesenheiten berücksichtigen.','Notwendige Bereiche und Mindest-/Maximalbesetzung bestimmen.','Skillmatrix prüfen; nur ausreichend qualifizierte Personen einsetzen.','Fixpersonen und festgelegte Bereichszuordnungen berücksichtigen.','PPD grundsätzlich mit maximal 8 Personen planen.','AS Picken grundsätzlich mit 4 Personen planen, soweit Bedarf und Verfügbarkeit dies zulassen.','PPD Sortierung grundsätzlich mit 1 geeigneten Mitarbeiter besetzen.','Personen mit Führungs- oder fest definierten Sonderaufgaben nicht entgegen der geltenden Ausschlussregel normal verplanen.','Bei Notfallbesetzung die dafür definierte Mindestqualifikation beachten.','Plan auf gleichzeitige Doppelzuordnung und fehlende Pflichtskills prüfen.','Freigegebenen Plan bereitstellen und notwendige Tagesänderungen dokumentieren.'],checks:['Keine Doppelbelegung.','Pflichtqualifikation je Bereich erfüllt.','Fix-/Ausschlussregeln eingehalten.'],deviations:['Bei unzureichender qualifizierter Besetzung Prioritäten und Bereiche durch die Führungskraft neu bewerten; Qualifikationsanforderungen nicht stillschweigend unterschreiten.'],records:['Schicht-/Einsatzplan','Abweichende Tagesänderung'],metrics:['Unterbesetzte Bereiche','Qualifikationsbedingte Umbesetzungen'],relatedDocuments:['SOP-QM-002 – Rollen, Verantwortlichkeiten und Qualifikation','SOP-ORG-003 – Leistungs- und KPI-Erfassung'],references:['SOP-QM-002','SOP-ORG-003']}),

  define({number:'SOP-ORG-003',title:'Leistungs- und KPI-Erfassung',area:'Organisation',keywords:['KPI','Leistung','Produktivität','PPD','AS picken'],processOwner:'Lagerführung',scope:'Operative Leistungs- und KPI-Erfassung im Lager',purpose:'Leistungsdaten einheitlich erfassen und für Kapazitäts-, Prozess- und Verbesserungsentscheidungen verwenden, ohne Kontextfaktoren zu ignorieren.',processFlow:['Zeit erfassen','Leistung erfassen','Kennzahl berechnen','Plausibilisieren','Auswerten'],responsibilities:['Verantwortliche erfassen beziehungsweise prüfen die Leistungsdaten.','Führungskräfte bewerten Kennzahlen im Prozesskontext.'],prerequisites:['Bereich, Arbeitszeit und erbrachte Leistung sind bekannt.'],resources:['ExportHUB KPI/Tagesleistung','D365-Transaktionsdaten soweit verwendet'],steps:['Datum und Arbeitsbereich auswählen.','Tatsächliche Start- und Endzeit beziehungsweise produktive Stunden erfassen.','Erbrachte Leistung für denselben Zeitraum eintragen.','Notwendige Notiz zu besonderen Einflüssen ergänzen.','Leistung pro Stunde nach der definierten Berechnung bestimmen.','Tageswert auf offensichtliche Eingabe- oder Zeitraumfehler prüfen.','Entwicklung über mehrere Tage betrachten und nicht nur einen Einzelwert bewerten.','Aktuelle Orientierungswerte berücksichtigen: PPD Mindestziel 55 und Soll 60,5; AS Picken Soll 200; PPD Sortierung Soll 80.','Abweichungen mit Prozessbedingungen wie Materialmangel, Störung, Einarbeitung oder Sonderaufgaben bewerten.','Ergebnisse für Kapazitätsplanung und kontinuierliche Verbesserung verwenden.','Änderung eines Zielwertes nachvollziehbar freigeben und dokumentieren.'],checks:['Zeit und Leistung beziehen sich auf denselben Zeitraum.','Zielwert ist die aktuell freigegebene Fassung.'],deviations:['D365-Transaktionsauswertung und besondere WorkClass-Filter werden gemäß SOP XXXX durchgeführt.'],records:['Tagesleistung','KPI-Verlauf','Notizen/Einflussfaktoren'],metrics:['PPD 55 Mindestziel / 60,5 Soll','AS Picken 200 Soll','PPD Sortierung 80 Soll'],relatedDocuments:['SOP-QM-005 – Interne Prüfung und kontinuierliche Verbesserung','SOP-ORG-002 – Schicht- und Personaleinsatzplanung'],references:['SOP-QM-005','SOP-ORG-002']})
